class FenwickTree2D:
    """2D Fenwick Tree (Binary Indexed Tree).

    Supports point updates and sub-rectangle sum queries in O(log R * log C).

    Notes on indexing:
    - This implementation follows the same 0-based external API style as the
      provided 1D FenwickTree (special-casing index 0 updates/queries).
    - Internally it stores a 2D array `tree` with shape (rows, cols).

    query(r1, c1, r2, c2) returns the sum over the rectangle:
        rows in [r1, r2) and cols in [c1, c2)
    """

    def __init__(self, rows: int, cols: int) -> None:
        if rows <= 0 or cols <= 0:
            raise ValueError("rows and cols must be positive")
        self.rows = rows
        self.cols = cols
        self.tree = [[0] * cols for _ in range(rows)]

    @staticmethod
    def next_(index: int) -> int:
        # Same bit trick as 1D FenwickTree.next_
        return index + (index & (-index))

    @staticmethod
    def prev(index: int) -> int:
        # Same bit trick as 1D FenwickTree.prev
        return index - (index & (-index))

    def add(self, r: int, c: int, val: int) -> None:
        """Add `val` to cell (r, c) in O(log R * log C)."""
        if not (0 <= r < self.rows and 0 <= c < self.cols):
            raise IndexError("(r, c) out of bounds")

        # Mirror the 1D implementation: special-case index 0, because next_(0)=0.
        if r == 0 and c == 0:
            self.tree[0][0] += val
            return

        rr = r
        while rr < self.rows:
            if rr == 0:
                # Only move along columns; keep row fixed to 0 to avoid next_(0) loop.
                cc = c
                if cc == 0:
                    self.tree[0][0] += val
                else:
                    while cc < self.cols:
                        self.tree[0][cc] += val
                        cc = self.next_(cc)
                # rr stays 0 forever; we're done.
                return

            cc = c
            if cc == 0:
                # Only move along rows; keep col fixed to 0 to avoid next_(0) loop.
                self.tree[rr][0] += val
            else:
                while cc < self.cols:
                    self.tree[rr][cc] += val
                    cc = self.next_(cc)

            rr = self.next_(rr)

    def _prefix(self, r: int, c: int) -> int:
        """Sum over rectangle [0, r) x [0, c) in O(log R * log C)."""
        if r <= 0 or c <= 0:
            return 0

        res = 0
        rr = r - 1  # make inclusive, like 1D prefix()
        while rr >= 0:
            if rr == 0:
                # Only move along columns; keep rr fixed at 0.
                cc = c - 1
                while cc >= 0:
                    res += self.tree[0][cc]
                    if cc == 0:
                        break
                    cc = self.prev(cc)
                break

            cc = c - 1
            while cc >= 0:
                res += self.tree[rr][cc]
                if cc == 0:
                    break
                cc = self.prev(cc)

            rr = self.prev(rr)
        return res

    def query(self, r1: int, c1: int, r2: int, c2: int) -> int:
        """Sum over rectangle [r1, r2) x [c1, c2) in O(log R * log C)."""
        if not (0 <= r1 <= r2 <= self.rows and 0 <= c1 <= c2 <= self.cols):
            raise IndexError("Invalid query rectangle bounds")
        return (
            self._prefix(r2, c2)
            - self._prefix(r1, c2)
            - self._prefix(r2, c1)
            + self._prefix(r1, c1)
        )
